// Writes ../THIRD-PARTY-NOTICES.md: every package that ends up inside graph-bundle.js, with its licence text,
// plus the two bundled fonts. Run it after rebuilding the bundle, so the notices match what is shipped.
// Usage: cd vendor && npm ci && node notices.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildSync } from 'esbuild';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const meta = buildSync({ entryPoints: [path.join(HERE, 'entry.js')], bundle: true, write: false, metafile: true, absWorkingDir: HERE, logLevel: 'silent' }).metafile;
const names = new Set();
for (const f of Object.keys(meta.inputs)) {
  const m = f.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//g);
  if (m) names.add(m[m.length - 1].replace('node_modules/', '').replace(/\/$/, ''));
}
const pkgs = [...names].sort().map(n => {
  const dir = path.join(HERE, 'node_modules', n);
  const p = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
  const lf = fs.readdirSync(dir).find(f => /^(licen[sc]e|copying)/i.test(f));
  if (!lf) throw new Error('no licence file in ' + n);
  return { name: n, version: p.version, license: p.license, text: fs.readFileSync(path.join(dir, lf), 'utf8').replace(/\r/g, '').trim() };
});
const fonts = [
  ['Newsreader', 'OFL-Newsreader.txt', 'newsreader-roman.woff2, newsreader-italic.woff2'],
  ['IBM Plex Mono', 'OFL-IBM-Plex-Mono.txt', 'plex400.woff2, plex500.woff2']
].map(([name, file, files]) => ({ name, file, files, notice: fs.readFileSync(path.join(HERE, 'fonts', file), 'utf8').replace(/\r/g, '').split('\n')[0].trim() }));
const out = [];
out.push('# Third-party notices', '',
  'Dialogic itself is under the MIT licence (see `LICENSE`). The viewer it builds also contains the software and fonts below, each under its own licence.', '',
  'This file is generated by `vendor/notices.mjs` from the packages that are actually bundled into `vendor/graph-bundle.js`.', '',
  '## Fonts', '',
  'Both fonts are licensed under the SIL Open Font License, Version 1.1. The full licence text is beside the font files.', '');
for (const f of fonts) out.push('- **' + f.name + '** (`vendor/fonts/`: ' + f.files + '). Licence: `vendor/fonts/' + f.file + '`.', '  ' + f.notice.split(/ (?=[A-Za-z]+-[A-Za-z\[\],]+\.ttf:)/)[0], '');
out.push('## JavaScript libraries bundled in `vendor/graph-bundle.js`', '', '| Package | Version | Licence |', '|---|---|---|');
for (const p of pkgs) out.push('| ' + p.name + ' | ' + p.version + ' | ' + p.license + ' |');
out.push('', '## Licence texts', '');
for (const p of pkgs) out.push('### ' + p.name + ' ' + p.version + ' (' + p.license + ')', '', '```', p.text, '```', '');
fs.writeFileSync(path.join(HERE, '..', 'THIRD-PARTY-NOTICES.md'), out.join('\n'));
console.log('wrote THIRD-PARTY-NOTICES.md: ' + pkgs.length + ' packages, ' + fonts.length + ' fonts');
